function exists(o,k){return Object.prototype.hasOwnProperty.call(o,k)&&o[k]!==null&&o[k]!==undefined&&o[k]!==''}
async function saveGeneral(ev){if(!coach()||saving)return;ev.preventDefault();ev.stopImmediatePropagation();saving=true;try{const m=matchBy(document.getElementById('match-stats-id-input')?.value);if(!m)throw Error('No se ha encontrado el partido.');const c=db(),who=await ident(),eid=await eventId(m);if(!c||!eid)throw Error('No se ha encontrado el partido en Supabase.');const payload=formStats(m),status=String(document.getElementById('stats-publication-status')?.value||'draft'),visible=[...document.querySelectorAll('[data-stats-visible]:checked')].map(x=>String(x.dataset.statsVisible||'')).filter(k=>exists(payload,k));if(status==='published'&&!Object.keys(payload).length)throw Error('Añade al menos una estadística antes de publicar.');const now=new Date().toISOString(),{data:old}=await c.from('match_statistics').select('published_at').eq('event_id',eid).maybeSingle();const rec={event_id:eid,club_id:who.profile.club_id,team_id:teamId(m,who),status:['draft','published','archived'].includes(status)?status:'draft',visible_metrics:visible,payload,published_at:status==='published'?now:(old?.published_at||null),created_by:who.profile.id,updated_at:now};const{error}=await c.from('match_statistics').upsert(rec,{onConflict:'event_id'});if(error)throw error;document.getElementById('modal-edit-match-stats')?.classList.remove('active');toast(status==='published'?'Estadística guardada y publicada.':'Estadística general guardada.');if(typeof window.renderStats==='function')await window.renderStats()}catch(e){console.error('[MatchStatsV2 general]',e);toast(e.message||'No se ha podido guardar.','error')}finally{saving=false}}
function cardId(card){const text=[...card.querySelectorAll('[onclick]')].map(x=>x.getAttribute('onclick')||'').find(x=>/(openMatchStatsModal|quickPublishMatchStats|archiveMatchStats)/.test(x))||'';return text.match(/(?:openMatchStatsModal|quickPublishMatchStats|archiveMatchStats)\(['\"]([^'\"]+)['\"]\)/)?.[1]||card.dataset.matchId||null}
function scan(){if(!coach())return;const root=document.getElementById('stats-matches-list');if(!root)return;root.querySelectorAll('.match-stat-card').forEach(card=>{if(card.querySelector('.ind-btn-v2'))return;const id=cardId(card);if(!id)return;const b=document.createElement('button');b.type='button';b.className='ind-btn-v2';b.textContent='Individuales (opcional)';b.onclick=e=>{e.preventDefault();e.stopPropagation();openIndividuals(id)};(card.querySelector('.stats-card-actions')||card.querySelector('.coach-match-expanded')||card).appendChild(b)});if(!observer){observer=new MutationObserver(()=>requestAnimationFrame(scan));observer.observe(root,{childList:true,subtree:true})}}
