async function renderList(){const body=document.getElementById('ind-body-v2');if(!body)return;body.innerHTML='<div class="ind-banner-v2"><div><strong>Completamente opcional.</strong><br>Puedes publicar solo las jugadoras que hayas registrado.</div><button type="button" class="btn btn-outline btn-sm" id="ind-close-v2">Seguir solo con generales</button></div><div>Cargando…</div>';body.querySelector('#ind-close-v2').onclick=()=>document.getElementById('ind-modal-v2')?.remove();const arr=[];for(const p of players()){let rid=null;try{rid=await playerId(p)}catch(_){}arr.push({p,rid,row:rid?individualRows.get(String(rid)):null})}const list=document.createElement('div');list.className='ind-list-v2';list.innerHTML=arr.map(({p,rid,row})=>`<div class="ind-row-v2"><div class="ind-avatar-v2">${esc(initials(p.name))}</div><div class="ind-name-v2"><strong>${esc(p.name||'Jugadora')}</strong><small>${p.number??p.dorsal?`Dorsal ${esc(p.number??p.dorsal)}`:'Sin dorsal'}</small></div><span class="ind-status-v2 ${row?.status||''}">${row?.status==='published'?'Publicado':row?.status==='draft'?'Borrador':'Sin datos'}</span><button type="button" class="ind-edit-v2" data-p="${esc(p.id)}" ${rid?'':'disabled'}>Editar</button></div>`).join('');body.querySelector(':scope > div:last-child')?.remove();body.appendChild(list);list.querySelectorAll('[data-p]').forEach(b=>b.onclick=()=>editPlayer(b.dataset.p))}
