function iv(id){return n(document.getElementById(id)?.value,'int')}
function preview(){const rp=iv('ir-p'),rn=iv('ir-n'),re=iv('ir-e'),rt=(rp||0)+(rn||0)+(re||0),r=document.getElementById('ir-prev');if(r)r.textContent=rt?`Total ${rt} · perfecta ${r1((rp||0)/rt*100)}% · neutra ${r1((rn||0)/rt*100)}% · error ${r1((re||0)/rt*100)}%`:'Sin datos';const at=iv('ia-t'),ap=iv('ia-p'),ae=iv('ia-e'),a=document.getElementById('ia-prev');if(a)a.textContent=at?`Efectividad ${r1(((ap||0)-(ae||0))/at*100)}%`:'Sin datos';const stt=iv('is-t'),sa=iv('is-a'),se=iv('is-e'),s=document.getElementById('is-prev');if(s)s.textContent=stt?`${sa||0} aces · error ${r1((se||0)/stt*100)}%`:'Sin datos'}
function payload(){const p={},v=[],rp=iv('ir-p'),rn=iv('ir-n'),re=iv('ir-e');if([rp,rn,re].some(x=>x!=null)){const t=(rp||0)+(rn||0)+(re||0);p.recPerfect=rp||0;p.recNeutral=rn||0;p.recErrors=re||0;p.recTotal=t;if(t){p.recPerfectPct=r1((rp||0)/t*100);p.recExclamPct=r1((rn||0)/t*100);p.recErrorPct=r1((re||0)/t*100);v.push('recPerfectPct','recExclamPct','recErrorPct','recTotal')}}const at=iv('ia-t'),ap=iv('ia-p'),ae=iv('ia-e');if([at,ap,ae].some(x=>x!=null)){if(!at)throw Error('En ataque, indica el total de ataques.');p.attackTotal=at;p.attackPoints=ap||0;p.attackErrors=ae||0;p.attackEfficiencyPct=r1(((ap||0)-(ae||0))/at*100);v.push('attackEfficiencyPct','attackErrors','attackTotal')}const stt=iv('is-t'),sa=iv('is-a'),se=iv('is-e');if([stt,sa,se].some(x=>x!=null)){if(!stt)throw Error('En saque, indica el total de saques.');p.serveTotal=stt;p.aces=sa||0;p.serveErrors=se||0;p.serveErrorPct=r1((se||0)/stt*100);v.push('aces','serveErrorPct','serveTotal')}const bp=iv('ib-p'),bt=iv('ib-t');if([bp,bt].some(x=>x!=null)){p.bloqueos=bp||0;v.push('bloqueos');if(bt!=null){p.blockTotal=bt;v.push('blockTotal')}}return{p,v:[...new Set(v)]}}
async function savePlayer(pl,pid,status){try{const c=db(),who=await ident(),m=matchBy(activeMatchId),{p,v}=payload();if(!c||!m||!activeEventId)throw Error('No se ha encontrado el partido.');if(status==='published'&&!v.length)throw Error('Añade al menos una estadística antes de publicar.');const now=new Date().toISOString(),old=individualRows.get(String(pid)),rec={event_id:activeEventId,player_id:pid,club_id:who.profile.club_id,team_id:teamId(m,who),status,visible_metrics:v,payload:p,published_at:status==='published'?now:(old?.published_at||null),created_by:who.profile.id,updated_at:now};const{data,error}=await c.from('match_player_statistics').upsert(rec,{onConflict:'event_id,player_id'}).select(ROW_SELECT).single();if(error)throw error;individualRows.set(String(pid),data);toast(status==='published'?`Estadísticas de ${pl.name} publicadas.`:`Borrador de ${pl.name} guardado.`);renderList()}catch(e){console.error('[MatchStatsV2 player]',e);toast(e.message||'No se ha podido guardar.','error')}}
